import{_ as a,o as e,c as l,a2 as i}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"法律伦理与合规","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/法律伦理与合规.md","filePath":"安全方向/法律伦理与合规.md","lastUpdated":1792430298000}'),r={name:"安全方向/法律伦理与合规.md"};function d(o,t,s,h,n,c){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="法律伦理与合规" tabindex="-1">法律伦理与合规 <a class="header-anchor" href="#法律伦理与合规" aria-label="Permalink to &quot;法律伦理与合规&quot;">​</a></h1><blockquote><p>校内第 5 学期开设核心课「网络安全法律与伦理」。安全人最重要的不是技术上限，而是行为边界——这门课决定你能走多远。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>《网络安全法》《数据安全法》《个人信息保护法》构建了中国的网络安全法律体系；</li><li>渗透测试、取证、数据处理都必须在法律与授权框架内进行；</li><li>合规（等保测评、数据合规）本身就是一个专业岗位方向。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>网络安全法律体系：网络安全法、数据安全法、个人信息保护法、刑法相关条款（非法侵入、破坏计算机信息系统罪等）</li><li>授权与边界：渗透测试授权书、漏洞披露规范（漏洞报告与应急响应）</li><li>伦理与职业操守：安全研究人员的责任、漏洞奖励计划（SRC）</li><li>等保与合规基础：等级保护制度、数据分类分级概念</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>校内教材与课件</td><td>教材</td><td>课程主线</td></tr><tr><td>国家法律法规原文</td><td>文档</td><td>中国人大网 / 政府网站公开文本</td></tr><tr><td>中国信息安全测评中心 / 各级网信办</td><td>机构</td><td>政策与标准发布渠道</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li><strong>把合规变成肌肉记忆</strong>：练靶只进授权平台（校内实训、CTF、自建靶场），不碰未授权目标；</li><li>了解漏洞报告的正确姿势：通过 SRC 平台（各大厂商安全应急响应中心）提交，而非公开炫耀；</li><li>从事取证方向的同学，认真学习证据保全与司法鉴定规范。</li></ul><div class="danger custom-block"><p class="custom-block-title">底线</p><p>未经授权对他人系统进行扫描、攻击、数据窃取，无论出于何种目的，均可能构成违法犯罪。本指南所有技术页面默认只在授权环境中实践。</p></div>',11)])])}const b=a(r,[["render",d]]);export{u as __pageData,b as default};
